class DiscountCalculator:
    def __init__(self, discount_percent: float):
        self.discount_percent = discount_percent

    def apply_discount(self, price: float) -> float:
        if self.discount_percent < 0 or self.discount_percent > 100:
            raise ValueError("Discount percent must be between 0 and 100")
        return price * (1 - self.discount_percent / 100)


def calculate_discount(price: float, discount_percent: float) -> float:
    """Calculate the discounted price.

    Args:
        price: The original price
        discount_percent: The discount percentage (0-100)

    Returns:
        The price after discount is applied
    """
    if discount_percent < 0 or discount_percent > 100:
        raise ValueError("Discount percent must be between 0 and 100")
    return price * (1 - discount_percent / 100)


def apply_discount(price: float, percent: float) -> float:
    """Return price reduced by `percent` percent, rounded to 2 decimals."""
    if percent < 0 or percent > 100:
        raise ValueError("Discount percent must be between 0 and 100")
    return round(price * (1 - percent / 100), 2)

